package com.paytaxihub.controller;

import com.paytaxihub.entity.*;
import com.paytaxihub.auth.AuthSessionService;
import org.springframework.http.*;
import com.paytaxihub.repository.*;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.web.bind.annotation.*;
import java.io.IOException;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.time.LocalDateTime;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

/** Demo-only admin, owner-report, in-app notification and MFA endpoints. */
@RestController
@RequestMapping("/api")
public class DemoFeatureController {
 private final DriverRepository drivers; private final FleetOwnerRepository owners; private final VehicleRepository vehicles;
 private final RouteRepository routes; private final TripRepository trips; private final TransactionRepository transactions;
 private final UserRepository users; private final ShiftRepository shifts; private final AuthSessionService sessions;
 @org.springframework.beans.factory.annotation.Value("${app.session.cookie-secure:true}") private boolean secureCookie;
 private static final Map<Integer,List<Map<String,Object>>> NOTIFICATIONS = new ConcurrentHashMap<>();
 private static final Map<String,MfaChallenge> OWNER_MFA = new ConcurrentHashMap<>();
 private record MfaChallenge(Integer userId,long expiresAtMs,java.util.concurrent.atomic.AtomicInteger attempts){}
 @org.springframework.beans.factory.annotation.Value("${app.mfa.code:}") private String mfaCode;
 public DemoFeatureController(DriverRepository d,FleetOwnerRepository o,VehicleRepository v,RouteRepository r,TripRepository t,TransactionRepository tx,UserRepository u,ShiftRepository s,AuthSessionService sessions){drivers=d;owners=o;vehicles=v;routes=r;trips=t;transactions=tx;users=u;shifts=s;this.sessions=sessions;}
 private void role(String actual, User.Role... allowed){if(User.Role.Admin.name().equals(actual))return;for(User.Role r:allowed)if(r.name().equals(actual))return;throw new SecurityException("You do not have permission to perform this action.");}
 private FleetOwner own(Integer uid){return owners.findByUser_UserId(uid).orElseThrow(()->new SecurityException("Fleet owner profile not found."));}
 public static void notifyUser(Integer userId,String title,String message){NOTIFICATIONS.computeIfAbsent(userId,k->Collections.synchronizedList(new ArrayList<>())).add(Map.of("title",title,"message",message,"createdAt",LocalDateTime.now().toString(),"read",false));}
 public static boolean hasNotification(Integer userId){return !NOTIFICATIONS.getOrDefault(userId,List.of()).isEmpty();}
 public static String issueOwnerMfa(Integer userId){long now=System.currentTimeMillis();OWNER_MFA.values().removeIf(c->c.expiresAtMs()<now);String id=UUID.randomUUID().toString();OWNER_MFA.put(id,new MfaChallenge(userId,now+5*60*1000L,new java.util.concurrent.atomic.AtomicInteger()));return id;}
 @PostMapping("/admin/drivers/{id}/kyc") public Map<String,Object> kyc(@PathVariable Integer id,@RequestBody Map<String,Object> body,@RequestAttribute("authRole") String role){role(role,User.Role.Admin);Driver d=drivers.findById(id).orElseThrow();Driver.KycStatus newStatus;try{newStatus=Driver.KycStatus.valueOf(String.valueOf(body.getOrDefault("status","Verified")));}catch(IllegalArgumentException ex){throw new IllegalArgumentException("Invalid KYC status.");}d.setKycStatus(newStatus);drivers.save(d);return Map.of("driverId",id,"kycStatus",d.getKycStatus().name());}
 @PostMapping("/fleet/assign-driver") public Map<String,Object> assign(@RequestBody Map<String,Object> body,@RequestAttribute("authUserId") Integer uid,@RequestAttribute("authRole") String role){role(role,User.Role.FleetOwner);FleetOwner o=User.Role.Admin.name().equals(role)?owners.findById(Integer.valueOf(String.valueOf(body.get("fleetOwnerId")))).orElseThrow():own(uid);Driver d=drivers.findById(Integer.valueOf(String.valueOf(body.get("driverId")))).orElseThrow();d.setFleetOwner(o);drivers.save(d);return Map.of("message",User.Role.Admin.name().equals(role)?"Driver assigned to selected fleet.":"Driver assigned to your fleet.","driverId",d.getDriverId(),"fleetOwnerId",o.getFleetOwnerId());}
 @PostMapping("/fleet/assign-vehicle") public Map<String,Object> assignVehicle(@RequestBody Map<String,Object> body,@RequestAttribute("authUserId") Integer uid,@RequestAttribute("authRole") String role){role(role,User.Role.FleetOwner);FleetOwner o=User.Role.Admin.name().equals(role)?owners.findById(Integer.valueOf(String.valueOf(body.get("fleetOwnerId")))).orElseThrow():own(uid);Vehicle v=vehicles.findById(Integer.valueOf(String.valueOf(body.get("vehicleId")))).orElseThrow();if(v.getDriver()==null)throw new IllegalArgumentException("Assign a driver to the vehicle before assigning it to a fleet.");if(!User.Role.Admin.name().equals(role)&&(v.getDriver().getFleetOwner()==null||!Objects.equals(v.getDriver().getFleetOwner().getFleetOwnerId(),o.getFleetOwnerId())))throw new SecurityException("Vehicle driver must belong to your fleet.");if(User.Role.Admin.name().equals(role))v.getDriver().setFleetOwner(o);v.setFleetOwner(o);vehicles.save(v);drivers.save(v.getDriver());return Map.of("message",User.Role.Admin.name().equals(role)?"Vehicle assigned to selected fleet.":"Vehicle assigned to your fleet.","vehicleId",v.getVehicleId());}
 @GetMapping("/admin/fares") public List<Map<String,Object>> fares(@RequestAttribute("authRole") String role){role(role,User.Role.Admin);return routes.findAll().stream().map(r->Map.<String,Object>of("routeId",r.getRouteId(),"routeName",r.getRouteName(),"fareType",r.getFareType().name(),"fareRate",r.getFareRate(),"active",Boolean.TRUE.equals(r.getIsActive()))).toList();}
 @PutMapping("/admin/fares/{id}") public Map<String,Object> updateFare(@PathVariable Integer id,@RequestBody Map<String,Object> body,@RequestAttribute("authRole") String role){role(role,User.Role.Admin);Route r=routes.findById(id).orElseThrow();BigDecimal rate;try{rate=new BigDecimal(String.valueOf(body.get("fareRate")).trim());}catch(NumberFormatException ex){throw new IllegalArgumentException("Enter a valid fare rate.");}if(rate.signum()<=0||rate.compareTo(new BigDecimal("5000"))>0)throw new IllegalArgumentException("Fare rate must be greater than R0 and at most R5,000.");r.setFareRate(rate);if(body.containsKey("isActive"))r.setIsActive(Boolean.parseBoolean(String.valueOf(body.get("isActive"))));routes.save(r);return Map.of("routeId",r.getRouteId(),"fareRate",r.getFareRate(),"isActive",r.getIsActive());}
 @GetMapping("/notifications") public List<Map<String,Object>> notifications(@RequestAttribute("authUserId") Integer uid){return List.copyOf(NOTIFICATIONS.getOrDefault(uid,List.of()));}
 @PostMapping("/notifications/demo-push") public Map<String,Object> testPush(@RequestBody Map<String,Object> body,@RequestAttribute("authUserId") Integer uid){String title=String.valueOf(body.getOrDefault("title","PayTaxiHub alert"));String message=String.valueOf(body.getOrDefault("message","Demo notification"));notifyUser(uid,title,message);return Map.of("queued",true,"channel","in-app demo notification","message","Real device push requires provider credentials.");}
 @GetMapping("/reports/owner.csv") public void ownerCsv(HttpServletResponse response,@RequestAttribute("authUserId") Integer uid,@RequestAttribute("authRole") String role)throws IOException{role(role,User.Role.FleetOwner);Set<Integer> ids=visibleDriverIds(uid,role);response.setCharacterEncoding(StandardCharsets.UTF_8.name());response.setContentType("text/csv");response.setHeader("Content-Disposition","attachment; filename=paytaxihub-"+(User.Role.Admin.name().equals(role)?"platform":"owner")+"-report.csv");var w=response.getWriter();w.println("trip_id,driver_id,commuter_id,status,distance_km,fare_amount,start_time");for(Trip t:trips.findAll())if(t.getDriver()!=null&&ids.contains(t.getDriver().getDriverId()))w.printf(Locale.ROOT,"%d,%d,%d,%s,%s,%s,%s%n",t.getTripId(),t.getDriver().getDriverId(),t.getCommuter().getUserId(),t.getTripStatus(),t.getDistanceKm(),t.getFareAmount(),t.getStartTime());w.flush();}
 @GetMapping("/reports/owner.pdf") public void ownerPdf(HttpServletResponse response,@RequestAttribute("authUserId") Integer uid,@RequestAttribute("authRole") String role)throws IOException {
  role(role,User.Role.FleetOwner); Map<String,Object> summary=ownerSummary(uid,role);
  String content="PayTaxiHub "+(User.Role.Admin.name().equals(role)?"Platform Administration":"Fleet Owner")+" Report\nScope: "+summary.get("scope")+"\nFleet Owner ID: "+summary.get("fleetOwnerId")+"\nDrivers: "+summary.get("drivers")+"\nTrips: "+summary.get("trips")+"\nGross Fare Revenue: R"+summary.get("grossFareRevenue")+"\nGenerated: "+LocalDateTime.now()+"\n\nDemo report. Revenue represents trip fares, not audited settlements.";
  String escaped=content.replace("\\","\\\\").replace("(","\\(").replace(")","\\)").replace("\n","\\n");
  String stream="BT /F1 12 Tf 50 790 Td ("+escaped.replace("\\n",") Tj 0 -20 Td (")+ ") Tj ET";
  byte[] bytes=pdf(stream); response.setContentType("application/pdf"); response.setHeader("Content-Disposition","attachment; filename=paytaxihub-owner-report.pdf"); response.setContentLength(bytes.length); response.getOutputStream().write(bytes);
 }
 private byte[] pdf(String stream)throws IOException { java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream(); List<Integer> offsets=new ArrayList<>(); write(out,"%PDF-1.4\n"); String[] objs={"<< /Type /Catalog /Pages 2 0 R >>","<< /Type /Pages /Kids [3 0 R] /Count 1 >>","<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>","<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>","<< /Length "+stream.getBytes(StandardCharsets.US_ASCII).length+" >>\nstream\n"+stream+"\nendstream"}; for(int i=0;i<objs.length;i++){offsets.add(out.size());write(out,(i+1)+" 0 obj\n"+objs[i]+"\nendobj\n");} int xref=out.size();write(out,"xref\n0 6\n0000000000 65535 f \n");for(int o:offsets)write(out,String.format(Locale.ROOT,"%010d 00000 n \n",o));write(out,"trailer << /Size 6 /Root 1 0 R >>\nstartxref\n"+xref+"\n%%EOF");return out.toByteArray(); }
 private void write(java.io.ByteArrayOutputStream out,String value)throws IOException{out.write(value.getBytes(StandardCharsets.US_ASCII));}
 @GetMapping("/reports/owner-summary") public Map<String,Object> ownerSummary(@RequestAttribute("authUserId") Integer uid,@RequestAttribute("authRole") String role){role(role,User.Role.FleetOwner);Set<Integer> ids=visibleDriverIds(uid,role);List<Trip> ts=trips.findAll().stream().filter(t->t.getDriver()!=null&&ids.contains(t.getDriver().getDriverId())).toList();BigDecimal revenue=ts.stream().filter(t->t.getFareAmount()!=null).map(Trip::getFareAmount).reduce(BigDecimal.ZERO,BigDecimal::add);Map<String,Object> result=new LinkedHashMap<>();result.put("scope",User.Role.Admin.name().equals(role)?"platform":"fleet");result.put("fleetOwnerId",User.Role.Admin.name().equals(role)?null:own(uid).getFleetOwnerId());result.put("drivers",ids.size());result.put("trips",ts.size());result.put("grossFareRevenue",revenue);result.put("fleetOwners",User.Role.Admin.name().equals(role)?owners.count():1);result.put("vehicles",User.Role.Admin.name().equals(role)?vehicles.count():vehicles.findAll().stream().filter(v->v.getFleetOwner()!=null&&Objects.equals(v.getFleetOwner().getFleetOwnerId(),own(uid).getFleetOwnerId())).count());result.put("users",User.Role.Admin.name().equals(role)?users.count():0);result.put("transactions",User.Role.Admin.name().equals(role)?transactions.count():0);result.put("routes",User.Role.Admin.name().equals(role)?routes.count():0);result.put("shifts",User.Role.Admin.name().equals(role)?shifts.count():shifts.findAll().stream().filter(sh->ids.contains(sh.getDriver().getDriverId())).count());return result;}
 private Set<Integer> visibleDriverIds(Integer uid,String role){if(User.Role.Admin.name().equals(role))return drivers.findAll().stream().map(Driver::getDriverId).collect(java.util.stream.Collectors.toSet());FleetOwner o=own(uid);Set<Integer> ids=new HashSet<>();drivers.findAll().stream().filter(d->d.getFleetOwner()!=null&&Objects.equals(d.getFleetOwner().getFleetOwnerId(),o.getFleetOwnerId())).forEach(d->ids.add(d.getDriverId()));return ids;}
 @GetMapping("/admin/overview") public Map<String,Object> adminOverview(@RequestAttribute("authRole") String role){role(role,User.Role.Admin);return Map.of("users",users.count(),"drivers",drivers.count(),"fleetOwners",owners.count(),"vehicles",vehicles.count(),"routes",routes.count(),"trips",trips.count(),"transactions",transactions.count(),"shifts",shifts.count(),"pendingKyc",drivers.findAll().stream().filter(d->d.getKycStatus()==Driver.KycStatus.Pending).count(),"grossFareRevenue",trips.findAll().stream().filter(t->t.getFareAmount()!=null).map(Trip::getFareAmount).reduce(BigDecimal.ZERO,BigDecimal::add));}
 @PostMapping("/auth/mfa/verify") public ResponseEntity<Map<String,Object>> verifyMfa(@RequestBody Map<String,Object> body){
  String id=String.valueOf(body.get("challengeId")),code=body.get("code")==null?"":String.valueOf(body.get("code")).trim();
  MfaChallenge c=OWNER_MFA.get(id);
  if(c==null||c.expiresAtMs()<System.currentTimeMillis()){OWNER_MFA.remove(id);throw new SecurityException("Your verification session expired. Please sign in again.");}
  if(code.isEmpty())throw new IllegalArgumentException("Please enter your verification code.");
  if(c.attempts().incrementAndGet()>5){OWNER_MFA.remove(id);throw new SecurityException("Too many incorrect codes. Please sign in again.");}
  if(mfaCode==null||mfaCode.isBlank()||!java.security.MessageDigest.isEqual(mfaCode.getBytes(StandardCharsets.UTF_8),code.getBytes(StandardCharsets.UTF_8)))throw new SecurityException("That verification code is incorrect.");
  OWNER_MFA.remove(id);User user=users.findById(c.userId()).orElseThrow();String token=sessions.create(user);
  ResponseCookie cookie=ResponseCookie.from("PTH_SESSION",token).httpOnly(true).secure(secureCookie).sameSite("Lax").path("/api").maxAge(28800).build();
  return ResponseEntity.ok().header(HttpHeaders.SET_COOKIE,cookie.toString()).body(Map.of("verified",true,"user",Map.of("userId",user.getUserId(),"fullName",user.getFullName(),"email",user.getEmail(),"role",user.getRole().name()),"token",token,"expiresInSeconds",28800));
 }
}
